// PORTAL-04 — Google sign-in (OpenID Connect, authorization code + PKCE)
// through the API, against the isolated development database. No request ever
// reaches Google: real credentials are not available. The suite sets the
// GOOGLE_OAUTH_* variables (test values) before importing the application and
// replaces GoogleOidcClient by a subclass whose token exchange is local: it
// checks the PKCE verifier against the challenge the start route put in the
// URL, and answers an ID token SIGNED here with an RS256 key pair generated by
// the test — which the server then verifies with its real verification
// function against a local key set (nonce, audience, issuer, expiry, verified
// e-mail). Covers: start (URL, cookie attributes, Origin, validation, the
// unconfigured 503), the callback's failures (no/forged cookie, state
// mismatch, access_denied, closed sign-up, link_required, account_unavailable),
// the four resolutions (existing identity, verified e-mail, pending
// self-registration, new account), MFA (the fragment and API-211), returnTo,
// the API-205 flags, rate limits and the OpenAPI document.
//
// Fixture users carry a unique suffix and are deleted at the end (cascade
// removes their identities, tokens and profiles; their audit rows stay — the
// log is append-only). The suite writes `settings.selfRegistration.enabled` of
// the shared academy row and restores the stored settings in afterAll.
// Skipped when no database is reachable.
import { createHash } from 'node:crypto';
import type { NestExpressApplication } from '@nestjs/platform-express';
import { Test } from '@nestjs/testing';
import { PrismaPg } from '@prisma/adapter-pg';
import { config as loadDotenv } from 'dotenv';
import { SignJWT, createLocalJWKSet, exportJWK, generateKeyPair } from 'jose';
import type { JWTVerifyGetKey } from 'jose';
import request from 'supertest';
import type { Response as SupertestResponse } from 'supertest';
import { afterAll, beforeAll, describe, expect, it, vi } from 'vitest';
import { postgresUrlFromEnv } from '../src/config/database-url.js';
import { ENV_FILE_PATHS } from '../src/config/env-files.js';
import { PrismaClient } from '../src/generated/prisma/client.js';
import type { Prisma } from '../src/generated/prisma/client.js';

loadDotenv({ path: [...ENV_FILE_PATHS], quiet: true });
// Test values only — never a real Google client. Process variables beat the env files.
const CLIENT_ID = 'e2e-portal04.apps.googleusercontent.com';
const REDIRECT_URI = 'http://localhost:5173/api/auth/google/callback';
process.env['GOOGLE_OAUTH_CLIENT_ID'] = CLIENT_ID;
process.env['GOOGLE_OAUTH_CLIENT_SECRET'] = 'e2e-only-not-a-real-secret';
process.env['GOOGLE_OAUTH_REDIRECT_URI'] = REDIRECT_URI;
// A fixed TEST key for the MFA account (never a real one).
const TEST_MFA_KEY = Buffer.alloc(32, 9).toString('base64');
process.env['AUTH_MFA_ENCRYPTION_KEY'] = TEST_MFA_KEY;
// Each scenario speaks from its own documentation address (X-Forwarded-For), so the per-IP limits never mix.
process.env['TRUST_PROXY'] = 'loopback';

const { AppModule } = await import('../src/app.module.js');
const { APP_CREATE_OPTIONS, configureApp } = await import('../src/app.setup.js');
const { GoogleOidcClient, GoogleOidcError, GOOGLE_ISSUERS } = await import('../src/auth/google/google-oidc.client.js');
const { GOOGLE_OAUTH_CONFIG } = await import('../src/auth/google/google.config.js');
const { codeChallengeS256 } = await import('../src/auth/google/google-state.js');
const { PasswordService } = await import('../src/auth/password.service.js');
const { parseMfaKey, sealSecret } = await import('../src/auth/mfa/secret-box.js');
const { base32Decode, generateTotpSecret, totpCode, totpStep } = await import('../src/auth/mfa/totp.js');
const { ConfigService } = await import('@nestjs/config');
type GoogleOAuthConfig = import('../src/auth/google/google.config.js').GoogleOAuthConfig;

const DATABASE_URL = process.env['DATABASE_URL'] || postgresUrlFromEnv(process.env, 'app');
const RUN = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
const PASSWORD = 'Correct-Horse-Battery-9';
const START = '/api/auth/google/start';
const CALLBACK = '/api/auth/google/callback';
const STATE_COOKIE = 'aca_google';
const REFRESH_COOKIE = 'aca_refresh';
const NIL_ID = '00000000-0000-0000-0000-000000000000';

async function canConnect(url: string): Promise<boolean> {
  const client = new PrismaClient({ adapter: new PrismaPg({ connectionString: url, connectionTimeoutMillis: 3000 }) });
  try {
    await client.$queryRaw`SELECT 1`;
    return true;
  } catch {
    return false;
  } finally {
    await client.$disconnect();
  }
}

const available = DATABASE_URL ? await canConnect(DATABASE_URL) : false;

/** What the fake Google knows about one authorization code. */
interface IssuedCode {
  claims: Record<string, unknown>;
  nonce: string;
  codeChallenge: string;
}

/**
 * The token exchange, local: the code must be one the test registered, the
 * verifier must match the S256 challenge of that attempt's URL (PKCE), and the
 * answer is an ID token signed with the test's private key. Everything after
 * that — the verification — is the server's own code.
 */
class FakeGoogleOidcClient extends GoogleOidcClient {
  readonly codes = new Map<string, IssuedCode>();
  readonly exchanges: string[] = [];

  constructor(
    config: GoogleOAuthConfig,
    keys: JWTVerifyGetKey,
    private readonly signer: (claims: Record<string, unknown>) => Promise<string>,
  ) {
    super(config, keys);
  }

  protected override async exchangeCode(code: string, codeVerifier: string): Promise<string> {
    this.exchanges.push(code);
    const issued = this.codes.get(code);
    // A code works once, like at Google.
    this.codes.delete(code);
    if (!issued || codeChallengeS256(codeVerifier) !== issued.codeChallenge) throw new GoogleOidcError('exchange_failed');
    return this.signer({ nonce: issued.nonce, ...issued.claims });
  }
}

interface Attempt {
  state: string;
  nonce: string;
  codeChallenge: string;
  cookie: string;
  start: SupertestResponse;
}

function setCookies(res: SupertestResponse): string[] {
  const header = res.headers['set-cookie'];
  return Array.isArray(header) ? header : header ? [header] : [];
}

function cookieLine(res: SupertestResponse, name: string): string {
  return setCookies(res).find((line) => line.startsWith(`${name}=`)) ?? '';
}

function cookieValue(res: SupertestResponse, name: string): string | undefined {
  const line = cookieLine(res, name);
  if (!line) return undefined;
  const value = line.split(';')[0]!.slice(name.length + 1);
  return value.length > 0 ? value : undefined;
}

/** The Location of a 302 as path + query, and the fragment parameters. */
function locationOf(res: SupertestResponse): { path: string; query: Record<string, string>; fragment: Record<string, string> } {
  const location = String(res.headers['location'] ?? '');
  const [beforeHash, hash = ''] = location.split('#');
  const [path, search = ''] = beforeHash!.split('?');
  return { path: path!, query: Object.fromEntries(new URLSearchParams(search)), fragment: Object.fromEntries(new URLSearchParams(hash)) };
}

describe.skipIf(!available)('PORTAL-04 Google sign-in (e2e)', () => {
  let app: NestExpressApplication;
  let unconfigured: NestExpressApplication;
  let prisma: PrismaClient;
  let fake: InstanceType<typeof FakeGoogleOidcClient>;
  let passwordHash: string;
  let originalSettings: Prisma.JsonValue;
  let academyId: string;
  const createdUserIds: string[] = [];
  const newAccountEmails: string[] = [];
  let ipCounter = 0;
  let codeCounter = 0;
  let subCounter = 0;
  const mfaKey = parseMfaKey(TEST_MFA_KEY)!;

  const nextIp = () => `198.51.100.${(ipCounter += 1)}`;
  const nextSub = () => `g${RUN}${(subCounter += 1).toString().padStart(4, '0')}`;
  const email = (name: string) => `g-${name}-${RUN}@example.test`;
  const api = (target: NestExpressApplication = app) => request(target.getHttpServer());

  async function setSignUp(enabled: boolean): Promise<void> {
    const base = originalSettings && typeof originalSettings === 'object' && !Array.isArray(originalSettings) ? (originalSettings as Record<string, unknown>) : {};
    const selfRegistration = { ...(base['selfRegistration'] as Record<string, unknown> | undefined), enabled };
    await prisma.academy.update({ where: { id: academyId }, data: { settings: { ...base, selfRegistration } as Prisma.InputJsonValue } });
  }

  async function begin(ip: string, body: Record<string, unknown> = {}): Promise<Attempt> {
    const res = await api().post(START).set('X-Forwarded-For', ip).send(body);
    expect(res.status, JSON.stringify(res.body)).toBe(200);
    const url = new URL(res.body.url as string);
    const cookie = cookieValue(res, STATE_COOKIE);
    expect(cookie).toBeDefined();
    return {
      state: url.searchParams.get('state')!,
      nonce: url.searchParams.get('nonce')!,
      codeChallenge: url.searchParams.get('code_challenge')!,
      cookie: cookie!,
      start: res,
    };
  }

  /** Google's redirect back with a code that the fake exchanges for an ID token with these claims. */
  function finish(attempt: Attempt, claims: Record<string, unknown>, ip: string, cookie: string | null = attempt.cookie) {
    const code = `code-${RUN}-${(codeCounter += 1)}`;
    fake.codes.set(code, { claims: { email_verified: true, ...claims }, nonce: attempt.nonce, codeChallenge: attempt.codeChallenge });
    const req = api().get(CALLBACK).query({ code, state: attempt.state, scope: 'openid email profile', authuser: '0', prompt: 'consent' }).set('X-Forwarded-For', ip);
    return cookie === null ? req : req.set('Cookie', `${STATE_COOKIE}=${cookie}`);
  }

  async function signIn(claims: Record<string, unknown>, body: Record<string, unknown> = {}): Promise<SupertestResponse> {
    const ip = nextIp();
    const attempt = await begin(ip, body);
    return finish(attempt, claims, ip);
  }

  async function createUser(name: string, data: Partial<Prisma.UserUncheckedCreateInput> = {}): Promise<{ id: string; email: string }> {
    const user = await prisma.user.create({
      data: { email: email(name), fullName: `Google ${name}`, passwordHash, status: 'active', emailVerifiedAt: new Date(), ...data },
      select: { id: true, email: true },
    });
    createdUserIds.push(user.id);
    return { id: user.id, email: user.email! };
  }

  async function mark(): Promise<string> {
    const latest = await prisma.auditLog.findFirst({ orderBy: { id: 'desc' }, select: { id: true } });
    return latest?.id ?? NIL_ID;
  }

  const eventsOf = (markId: string, userId: string) =>
    prisma.auditLog.findMany({
      where: { id: { gt: markId }, entityId: userId },
      orderBy: { id: 'asc' },
      select: { action: true, actorUserId: true, metadata: true },
    });

  /** The state cookie is cleared on the callback's answer: empty value, Max-Age=0, the same path. */
  function expectStateCleared(res: SupertestResponse): void {
    const line = cookieLine(res, STATE_COOKIE);
    expect(line).toMatch(/^aca_google=;/);
    expect(line).toMatch(/Max-Age=0/);
    expect(line).toMatch(/Path=\/api\/auth\/google(;|$)/);
  }

  beforeAll(async () => {
    const pair = await generateKeyPair('RS256');
    const jwk = { ...(await exportJWK(pair.publicKey)), kid: 'e2e-google-key', alg: 'RS256', use: 'sig' };
    const keys = createLocalJWKSet({ keys: [jwk] });
    const signer = (claims: Record<string, unknown>) =>
      new SignJWT(claims)
        .setProtectedHeader({ alg: 'RS256', kid: 'e2e-google-key', typ: 'JWT' })
        .setIssuer(GOOGLE_ISSUERS[0]!)
        .setAudience(CLIENT_ID)
        .setIssuedAt()
        .setExpirationTime('1h')
        .sign(pair.privateKey);

    const moduleRef = await Test.createTestingModule({ imports: [AppModule] })
      .overrideProvider(GoogleOidcClient)
      .useFactory({
        factory: (config: GoogleOAuthConfig) => (fake = new FakeGoogleOidcClient(config, keys, signer)),
        inject: [GOOGLE_OAUTH_CONFIG],
      })
      .compile();
    app = moduleRef.createNestApplication<NestExpressApplication>(APP_CREATE_OPTIONS);
    configureApp(app);
    await app.init();

    // The same application on a server WITHOUT Google: no configuration for the routes, and API-205 reads no client values.
    const unconfiguredRef = await Test.createTestingModule({ imports: [AppModule] }).overrideProvider(GOOGLE_OAUTH_CONFIG).useValue(null).compile();
    unconfigured = unconfiguredRef.createNestApplication<NestExpressApplication>(APP_CREATE_OPTIONS);
    configureApp(unconfigured);
    await unconfigured.init();
    const config = unconfigured.get(ConfigService);
    const realGet = config.get.bind(config);
    vi.spyOn(config, 'get').mockImplementation(((key: string, ...rest: unknown[]) =>
      key.startsWith('GOOGLE_OAUTH_') ? undefined : (realGet as (k: string, ...r: unknown[]) => unknown)(key, ...rest)) as typeof config.get);

    prisma = new PrismaClient({ adapter: new PrismaPg({ connectionString: DATABASE_URL! }) });
    passwordHash = await new PasswordService().hash(PASSWORD);
    const academy = await prisma.academy.findFirstOrThrow({ select: { id: true, settings: true } });
    academyId = academy.id;
    originalSettings = academy.settings;
  });

  afterAll(async () => {
    vi.restoreAllMocks();
    if (prisma) {
      if (academyId) await prisma.academy.update({ where: { id: academyId }, data: { settings: originalSettings as Prisma.InputJsonValue } });
      const created = await prisma.user.findMany({ where: { email: { in: newAccountEmails } }, select: { id: true } });
      const ids = [...createdUserIds, ...created.map((user) => user.id)];
      if (ids.length > 0) await prisma.user.deleteMany({ where: { id: { in: ids } } });
      await prisma.$disconnect();
    }
    await app?.close();
    await unconfigured?.close();
  });

  it('start answers the authorization URL (code + PKCE S256, three scopes, state, nonce, account chooser) and sets the state cookie', async () => {
    const res = (await begin(nextIp(), { returnTo: '/catalog' })).start;
    const url = new URL(res.body.url as string);
    expect(Object.keys(res.body)).toEqual(['url']);
    expect(`${url.origin}${url.pathname}`).toBe('https://accounts.google.com/o/oauth2/v2/auth');
    expect(url.searchParams.get('response_type')).toBe('code');
    expect(url.searchParams.get('client_id')).toBe(CLIENT_ID);
    expect(url.searchParams.get('redirect_uri')).toBe(REDIRECT_URI);
    expect(url.searchParams.get('scope')).toBe('openid email profile');
    expect(url.searchParams.get('code_challenge_method')).toBe('S256');
    expect(url.searchParams.get('code_challenge')).toMatch(/^[A-Za-z0-9_-]{43}$/);
    expect(url.searchParams.get('state')).toMatch(/^[A-Za-z0-9_-]{43}$/);
    expect(url.searchParams.get('nonce')).toMatch(/^[A-Za-z0-9_-]{43}$/);
    expect(url.searchParams.get('prompt')).toBe('select_account');
    // The client secret never leaves the server.
    expect(res.body.url).not.toContain('e2e-only-not-a-real-secret');
    const line = cookieLine(res, STATE_COOKIE);
    expect(line).toMatch(/HttpOnly/);
    expect(line).toMatch(/SameSite=Lax/);
    expect(line).toMatch(/Path=\/api\/auth\/google(;|$)/);
    expect(line).toMatch(/Max-Age=600/);
    // AUTH_COOKIE_SECURE is false outside production — like the session cookie.
    expect(line).not.toMatch(/Secure/);
    expect(res.headers['cache-control']).toBe('no-store');
    expect(cookieLine(res, REFRESH_COOKIE)).toBe('');
  });

  it('start needs an acceptable Origin, refuses another field, and accepts any returnTo (reduced later); unconfigured → 503 google_unavailable', async () => {
    const foreign = await api().post(START).set({ 'X-Forwarded-For': nextIp(), Origin: 'https://evil.example' }).send({});
    expect(foreign.status).toBe(403);
    expect(foreign.body.code).toBe('origin_forbidden');
    const own = await api().post(START).set({ 'X-Forwarded-For': nextIp(), Origin: 'http://localhost:5173' }).send({});
    expect(own.status).toBe(200);
    const extra = await api().post(START).set('X-Forwarded-For', nextIp()).send({ returnTo: '/', role: 'academy_admin' });
    expect(extra.status).toBe(400);
    for (const returnTo of [42, null, ['/x'], 'https://evil.example']) {
      expect((await api().post(START).set('X-Forwarded-For', nextIp()).send({ returnTo })).status, JSON.stringify(returnTo)).toBe(200);
    }
    const off = await api(unconfigured).post(START).set('X-Forwarded-For', nextIp()).send({});
    expect(off.status).toBe(503);
    expect(off.body).toMatchObject({ statusCode: 503, code: 'google_unavailable' });
    expect(cookieLine(off, STATE_COOKIE)).toBe('');
  });

  it('the callback answers failed without the cookie, with a forged or foreign cookie, and with another state — always a 302 that clears the cookie', async () => {
    const ip = nextIp();
    const attempt = await begin(ip, { returnTo: '/catalog' });
    const sub = nextSub();
    const claims = { sub, email: email('nocookie') };

    const missing = await finish(attempt, claims, ip, null);
    expect(missing.status).toBe(302);
    expect(locationOf(missing)).toMatchObject({ path: '/login', query: { google: 'failed', returnTo: '/' } });
    expectStateCleared(missing);
    expect(cookieLine(missing, REFRESH_COOKIE)).toBe('');

    const forged = await finish(attempt, claims, ip, `${attempt.cookie.slice(0, -4)}AAAA`);
    expect(locationOf(forged).query).toEqual({ google: 'failed', returnTo: '/' });
    expectStateCleared(forged);

    const other = await begin(ip);
    const crossed = await finish(attempt, claims, ip, other.cookie);
    expect(locationOf(crossed).query).toEqual({ google: 'failed', returnTo: '/' });

    // Nobody was created or linked, and the code exchange was never attempted for these.
    expect(await prisma.userIdentity.count({ where: { providerSubject: sub } })).toBe(0);
    expect(fake.exchanges).toHaveLength(0);
  });

  it('error=access_denied → cancelled (with the returnTo of the attempt); another Google error → failed', async () => {
    const ip = nextIp();
    const attempt = await begin(ip, { returnTo: '/my-school' });
    const denied = await api().get(CALLBACK).query({ error: 'access_denied', state: attempt.state }).set({ 'X-Forwarded-For': ip, Cookie: `${STATE_COOKIE}=${attempt.cookie}` });
    expect(denied.status).toBe(302);
    expect(locationOf(denied)).toMatchObject({ path: '/login', query: { google: 'cancelled', returnTo: '/my-school' } });
    expectStateCleared(denied);
    const broken = await api().get(CALLBACK).query({ error: 'server_error' }).set('X-Forwarded-For', ip);
    expect(locationOf(broken).query).toEqual({ google: 'failed', returnTo: '/' });
  });

  it('an ID token of another attempt (nonce) or with an unverified e-mail → failed, and nothing is written', async () => {
    const ip = nextIp();
    const attempt = await begin(ip);
    const sub = nextSub();
    const code = `code-${RUN}-nonce`;
    fake.codes.set(code, { claims: { sub, email: email('nonce'), email_verified: true, nonce: 'x'.repeat(43) }, nonce: 'x'.repeat(43), codeChallenge: attempt.codeChallenge });
    const wrongNonce = await api().get(CALLBACK).query({ code, state: attempt.state }).set({ 'X-Forwarded-For': ip, Cookie: `${STATE_COOKIE}=${attempt.cookie}` });
    expect(locationOf(wrongNonce).query).toEqual({ google: 'failed', returnTo: '/' });

    await setSignUp(true);
    const unverified = await signIn({ sub, email: email('unverified-google'), email_verified: false });
    expect(locationOf(unverified).query).toEqual({ google: 'failed', returnTo: '/' });
    expect(await prisma.user.count({ where: { email: { in: [email('nonce'), email('unverified-google')] } } })).toBe(0);
    expect(await prisma.userIdentity.count({ where: { providerSubject: sub } })).toBe(0);
  });

  it('a new person while sign-up is open → a student account with a confirmed address, the identity, the events and a session cookie that refreshes', async () => {
    await setSignUp(true);
    const address = email('new');
    newAccountEmails.push(address);
    const sub = nextSub();
    const m = await mark();
    const res = await signIn({ sub, email: address.toUpperCase(), name: '  New   Learner ' }, { returnTo: '/catalog/abc?intent=enroll' });
    expect(res.status).toBe(302);
    expect(locationOf(res)).toEqual({ path: '/auth/google/done', query: { returnTo: '/catalog/abc?intent=enroll' }, fragment: {} });
    expectStateCleared(res);
    const refreshLine = cookieLine(res, REFRESH_COOKIE);
    expect(refreshLine).toMatch(/HttpOnly/);
    expect(refreshLine).toMatch(/SameSite=Strict/);
    expect(refreshLine).toMatch(/Path=\/api\/auth(;|$)/);
    expect(res.headers['cache-control']).toBe('no-store');

    const user = await prisma.user.findUniqueOrThrow({
      where: { email: address },
      select: { id: true, status: true, emailVerifiedAt: true, passwordHash: true, fullName: true, roles: { select: { role: { select: { key: true } } } }, studentProfile: { select: { userId: true } } },
    });
    expect(user).toMatchObject({ status: 'active', passwordHash: null, fullName: 'New Learner' });
    expect(user.emailVerifiedAt).not.toBeNull();
    expect(user.roles.map((grant) => grant.role.key)).toEqual(['student']);
    expect(user.studentProfile).not.toBeNull();
    const identity = await prisma.userIdentity.findUniqueOrThrow({ where: { provider_providerSubject: { provider: 'google', providerSubject: sub } } });
    expect(identity).toMatchObject({ userId: user.id, email: address });
    expect(identity.lastUsedAt).not.toBeNull();

    const events = await eventsOf(m, user.id);
    expect(events.map((event) => event.action)).toEqual(['users.self_registered', 'auth.google.linked', 'auth.login.succeeded']);
    expect(events[0]).toMatchObject({ actorUserId: user.id, metadata: { via: 'google' } });
    expect(events[1]).toMatchObject({ actorUserId: user.id, metadata: { via: 'new_account' } });
    expect(events[2]).toMatchObject({ actorUserId: user.id, metadata: { via: 'google' } });
    const text = JSON.stringify(events);
    for (const secret of [address, sub, cookieValue(res, REFRESH_COOKIE)!]) expect(text).not.toContain(secret);

    // The cookie is a real session: the done page's refresh answers the new student.
    const refreshed = await api().post('/api/auth/refresh').set('Cookie', `${REFRESH_COOKIE}=${cookieValue(res, REFRESH_COOKIE)}`).expect(200);
    expect(refreshed.body.user).toMatchObject({ id: user.id, email: address, roles: ['student'] });

    // The second sign-in with the same Google account is the existing identity: no new account, no new link event.
    const again = await signIn({ sub, email: address });
    expect(locationOf(again).path).toBe('/auth/google/done');
    expect(await prisma.user.count({ where: { email: address } })).toBe(1);
    const linkEvents = await prisma.auditLog.count({ where: { id: { gt: m }, entityId: user.id, action: 'auth.google.linked' } });
    expect(linkEvents).toBe(1);
  });

  it('a new person while sign-up is closed → registration_closed, nothing created', async () => {
    await setSignUp(false);
    const address = email('closed');
    newAccountEmails.push(address);
    const res = await signIn({ sub: nextSub(), email: address }, { returnTo: '/catalog' });
    expect(locationOf(res)).toMatchObject({ path: '/login', query: { google: 'registration_closed', returnTo: '/catalog' } });
    expect(cookieLine(res, REFRESH_COOKIE)).toBe('');
    expect(await prisma.user.count({ where: { email: address } })).toBe(0);
  });

  it('an existing identity signs in whatever the sign-up setting, and its last use is stamped', async () => {
    await setSignUp(false);
    const user = await createUser('identity');
    const sub = nextSub();
    const identity = await prisma.userIdentity.create({ data: { userId: user.id, provider: 'google', providerSubject: sub, email: user.email } });
    const m = await mark();
    // Google may report another address later: the subject is the key, never the e-mail.
    const res = await signIn({ sub, email: email('identity-renamed') });
    expect(locationOf(res)).toEqual({ path: '/auth/google/done', query: { returnTo: '/' }, fragment: {} });
    expect(cookieValue(res, REFRESH_COOKIE)).toBeDefined();
    expect((await prisma.userIdentity.findUniqueOrThrow({ where: { id: identity.id } })).lastUsedAt).not.toBeNull();
    expect((await eventsOf(m, user.id)).map((event) => event.action)).toEqual(['auth.login.succeeded']);
  });

  it('an active account with a confirmed address is linked (verified_email) and signed in', async () => {
    const user = await createUser('verified');
    const sub = nextSub();
    const m = await mark();
    const res = await signIn({ sub, email: user.email });
    expect(locationOf(res).path).toBe('/auth/google/done');
    expect(await prisma.userIdentity.findUnique({ where: { provider_providerSubject: { provider: 'google', providerSubject: sub } }, select: { userId: true } })).toEqual({ userId: user.id });
    const events = await eventsOf(m, user.id);
    expect(events.map((event) => event.action)).toEqual(['auth.google.linked', 'auth.login.succeeded']);
    expect(events[0]!.metadata).toEqual({ via: 'verified_email' });
    // The password still works: nothing about the account changed but the link.
    expect((await prisma.user.findUniqueOrThrow({ where: { id: user.id }, select: { passwordHash: true } })).passwordHash).toBe(passwordHash);

    // Another Google account with the same address is never swapped in.
    const other = await signIn({ sub: nextSub(), email: user.email });
    expect(locationOf(other).query).toEqual({ google: 'link_required', returnTo: '/' });
  });

  it('an account without a confirmed address, or only invited → link_required, nothing linked', async () => {
    const unverified = await createUser('unverified', { emailVerifiedAt: null });
    const invited = await createUser('invited', { status: 'invited', passwordHash: null, emailVerifiedAt: null });
    for (const user of [unverified, invited]) {
      const res = await signIn({ sub: nextSub(), email: user.email }, { returnTo: '/profile' });
      expect(locationOf(res), user.email).toMatchObject({ path: '/login', query: { google: 'link_required', returnTo: '/profile' } });
      expect(cookieLine(res, REFRESH_COOKIE)).toBe('');
      expect(await prisma.userIdentity.count({ where: { userId: user.id } })).toBe(0);
    }
    expect((await prisma.user.findUniqueOrThrow({ where: { id: invited.id }, select: { status: true } })).status).toBe('invited');
  });

  it('a pending self-registered account (no password) becomes active with a confirmed address, its open links retired, and is linked', async () => {
    const user = await createUser('pending', { status: 'pending', passwordHash: null, emailVerifiedAt: null });
    const token = await prisma.verificationToken.create({
      data: {
        userId: user.id,
        purpose: 'email_verification',
        tokenHash: createHash('sha256').update(`pending-${RUN}`).digest('hex'),
        metadata: { via: 'self_registration' },
        expiresAt: new Date(Date.now() + 60 * 60 * 1000),
      },
    });
    const m = await mark();
    const res = await signIn({ sub: nextSub(), email: user.email });
    expect(locationOf(res).path).toBe('/auth/google/done');
    const after = await prisma.user.findUniqueOrThrow({ where: { id: user.id }, select: { status: true, emailVerifiedAt: true, passwordHash: true } });
    expect(after.status).toBe('active');
    expect(after.emailVerifiedAt).not.toBeNull();
    expect(after.passwordHash).toBeNull();
    expect((await prisma.verificationToken.findUniqueOrThrow({ where: { id: token.id } })).consumedAt).not.toBeNull();
    const events = await eventsOf(m, user.id);
    expect(events.map((event) => event.action)).toEqual(['auth.google.linked', 'auth.login.succeeded']);
    expect(events[0]!.metadata).toEqual({ via: 'pending_registration' });
  });

  it('a suspended, archived, soft-deleted or locked account → account_unavailable, no failed login counted', async () => {
    const suspended = await createUser('suspended', { status: 'suspended' });
    const archived = await createUser('archived', { status: 'archived' });
    const deleted = await createUser('deleted', { deletedAt: new Date(), status: 'archived' });
    const locked = await createUser('locked', { lockedUntil: new Date(Date.now() + 10 * 60 * 1000), failedLoginCount: 5 });
    for (const user of [suspended, archived, deleted, locked]) {
      const res = await signIn({ sub: nextSub(), email: user.email });
      expect(locationOf(res).query, user.email).toEqual({ google: 'account_unavailable', returnTo: '/' });
      expect(cookieLine(res, REFRESH_COOKIE)).toBe('');
      expect(await prisma.userIdentity.count({ where: { userId: user.id } })).toBe(0);
    }
    expect((await prisma.user.findUniqueOrThrow({ where: { id: locked.id }, select: { failedLoginCount: true, lockedUntil: true } })).failedLoginCount).toBe(5);

    // A linked identity of a suspended account opens nothing either.
    const sub = nextSub();
    await prisma.userIdentity.create({ data: { userId: suspended.id, provider: 'google', providerSubject: sub } });
    const viaIdentity = await signIn({ sub, email: suspended.email });
    expect(locationOf(viaIdentity).query).toEqual({ google: 'account_unavailable', returnTo: '/' });
  });

  it('an account with two-step verification gets no session: the challenge in the fragment, which API-211 finishes', async () => {
    const user = await createUser('mfa');
    const secret = generateTotpSecret();
    await prisma.user.update({ where: { id: user.id }, data: { mfaSecret: sealSecret(mfaKey, secret, user.id), mfaEnabledAt: new Date() } });
    const m = await mark();
    const res = await signIn({ sub: nextSub(), email: user.email }, { returnTo: '/my-school' });
    expect(res.status).toBe(302);
    const { path, query, fragment } = locationOf(res);
    expect(path).toBe('/login');
    expect(query).toEqual({});
    expect(Object.keys(fragment).sort()).toEqual(['expiresAt', 'google-mfa', 'returnTo']);
    expect(fragment['google-mfa']).toMatch(/^[A-Za-z0-9_-]{43}$/);
    expect(fragment['returnTo']).toBe('/my-school');
    expect(new Date(fragment['expiresAt']!).getTime()).toBeGreaterThan(Date.now());
    expect(cookieLine(res, REFRESH_COOKIE)).toBe('');
    expectStateCleared(res);
    // Linked, but no session event yet.
    expect((await eventsOf(m, user.id)).map((event) => event.action)).toEqual(['auth.google.linked']);

    const code = totpCode(base32Decode(secret)!, totpStep(Date.now()));
    const second = await api().post('/api/auth/login/mfa').set('X-Forwarded-For', nextIp()).send({ challenge: fragment['google-mfa'], code });
    expect(second.status, JSON.stringify(second.body)).toBe(200);
    expect(second.body.user.id).toBe(user.id);
    expect(cookieValue(second, REFRESH_COOKIE)).toBeDefined();
    expect((await eventsOf(m, user.id)).map((event) => event.action)).toEqual(['auth.google.linked', 'auth.login.succeeded']);
  });

  it('returnTo is carried from start to the redirect and reduced to a safe path', async () => {
    const user = await createUser('return');
    const sub = nextSub();
    await prisma.userIdentity.create({ data: { userId: user.id, provider: 'google', providerSubject: sub } });
    for (const [given, expected] of [
      ['/catalog/1?intent=enroll#top', '/catalog/1?intent=enroll#top'],
      ['https://evil.example/', '/'],
      ['//evil.example', '/'],
      ['/\\evil.example', '/'],
      ['/api/auth/me', '/'],
      ['/a b', '/'],
      [undefined, '/'],
    ] as const) {
      const res = await signIn({ sub, email: user.email }, given === undefined ? {} : { returnTo: given });
      expect(locationOf(res), String(given)).toEqual({ path: '/auth/google/done', query: { returnTo: expected }, fragment: {} });
    }
  });

  it('API-205 answers googleSignIn with the configuration and googleSignUp with the self-registration setting too; without Google both are false and the callback says unavailable', async () => {
    await setSignUp(false);
    expect((await api().get('/api/academy/public').expect(200)).body).toMatchObject({ googleSignIn: true, googleSignUp: false, selfRegistration: false });
    await setSignUp(true);
    // MAIL_TRANSPORT=none (vitest.config.e2e.ts): e-mail sign-up stays closed, Google sign-up opens.
    expect((await api().get('/api/academy/public').expect(200)).body).toMatchObject({ googleSignIn: true, googleSignUp: true, selfRegistration: false });
    expect((await api(unconfigured).get('/api/academy/public').expect(200)).body).toMatchObject({ googleSignIn: false, googleSignUp: false });

    const res = await api(unconfigured).get(CALLBACK).query({ code: 'c', state: 's' }).set('X-Forwarded-For', nextIp());
    expect(res.status).toBe(302);
    expect(locationOf(res).query).toEqual({ google: 'unavailable', returnTo: '/' });
    expectStateCleared(res);
  });

  it('rate limits: start 20 per 15 minutes per IP (429 JSON), the callback 30 — then still a 302 to failed', async () => {
    const ip = nextIp();
    let startCount = 0;
    let limitedStart: SupertestResponse | undefined;
    for (let i = 0; i < 25 && !limitedStart; i += 1) {
      const res = await api().post(START).set('X-Forwarded-For', ip).send({});
      if (res.status === 429) limitedStart = res;
      else startCount += 1;
    }
    expect(startCount).toBe(20);
    expect(limitedStart?.body).toMatchObject({ statusCode: 429, code: 'rate_limited' });

    const cbIp = nextIp();
    let limitedCallback: SupertestResponse | undefined;
    let callbackCount = 0;
    for (let i = 0; i < 35 && !limitedCallback; i += 1) {
      const res = await api().get(CALLBACK).query({ code: 'c', state: 's' }).set('X-Forwarded-For', cbIp);
      expect(res.status).toBe(302);
      if (res.headers['retry-after-login'] !== undefined) limitedCallback = res;
      else callbackCount += 1;
    }
    expect(callbackCount).toBe(30);
    expect(locationOf(limitedCallback!).query).toEqual({ google: 'failed', returnTo: '/' });
    expectStateCleared(limitedCallback!);
  });

  it(
    'the OpenAPI document lists both routes, public, with the start body and the 302 of the callback',
    async () => {
      const docs = await api().get('/api/docs-json').expect(200);
      const start = docs.body.paths[START]?.post;
      const callback = docs.body.paths[CALLBACK]?.get;
      expect(start).toBeDefined();
      expect(callback).toBeDefined();
      expect(start.security ?? []).toEqual([]);
      expect(callback.security ?? []).toEqual([]);
      expect(Object.keys(start.responses)).toEqual(expect.arrayContaining(['200', '403', '429', '503']));
      expect(callback.responses).toHaveProperty('302');
      expect(docs.body.components.schemas['GoogleStartResponseDto'].properties).toHaveProperty('url');
      expect(Object.keys(docs.body.components.schemas['AcademyPublicDto'].properties)).toEqual(expect.arrayContaining(['googleSignIn', 'googleSignUp']));
    },
    20_000,
  );
});
